/**
 * Formats a given date string into an ISO 8601 string without seconds.
 * @param inNewPicking - The date string to be formatted.
 * @returns The formatted ISO 8601 string.
 */
export function formatDate(inNewPicking: string): string {
  const myDate = new Date(Date.parse(inNewPicking));
  const year = myDate.getFullYear();
  const month = (myDate.getMonth() + 1).toString().padStart(2, '0');
  const day = myDate.getDate().toString().padStart(2, '0');
  const hours = myDate.getHours().toString().padStart(2, '0');
  const minutes = myDate.getMinutes().toString().padStart(2, '0');
  const iso8601String = `${year}-${month}-${day}T${hours}:${minutes}:00`;
  return iso8601String;
}

class AppLogger {
  public log(message: unknown): void {
    console.log(`${new Date().toISOString()} -- ${message}`);
  }

  public error(message: unknown, stack?: string): void {
    console.error(`${new Date().toISOString()} -- ${message}`, stack);
  }

  public warn(message: unknown): void {
    console.warn(`${new Date().toISOString()} -- ${message}`);
  }

  public debug(message: unknown): void {
    console.debug(`${new Date().toISOString()} -- ${message}`);
  }

  public verbose(message: unknown): void {
    console.info(`${new Date().toISOString()} -- ${message}`);
  }
}

export const appLogger = new AppLogger();

